package com.wizzadrds.theworldremembers.rumor; import com.wizzadrds.theworldremembers.memory.MemoryEventType; import org.junit.jupiter.api.Test; import java.util.UUID; import static org.junit.jupiter.api.Assertions.*; class KnowledgeManagerTest{@Test void reportedKnowledgeBecomesRumoredOnSecondHop(){var s=UUID.randomUUID();var f=new KnowledgeFact(UUID.randomUUID(),MemoryEventType.NPC_DIED,10,s,KnowledgeOrigin.DIRECT,100,10);var r=f.reported(20);var rr=r.reported(30);assertEquals(KnowledgeOrigin.RUMORED,rr.origin());assertTrue(rr.confidence()<r.confidence());}@Test void rumorDegradesWithAge(){var f=new KnowledgeFact(UUID.randomUUID(),MemoryEventType.NPC_MARRIED,10,UUID.randomUUID(),KnowledgeOrigin.RUMORED,80,0);assertTrue(f.degrade(48000).confidence()<80);}}
